#include <stdio.h>

typedef struct { int key; int idx; } Elem;

static long cmp_count = 0;
static int total_passes = 0;

void merge(Elem a[], Elem tmp[], int lo, int mid, int hi) {
    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) {
        cmp_count++;
        /* 相等时取左边 -> 保证稳定 */
        if (a[i].key <= a[j].key) tmp[k++] = a[i++];
        else                      tmp[k++] = a[j++];
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi)  tmp[k++] = a[j++];
    for (i = lo; i <= hi; i++) a[i] = tmp[i];
}

/* 自底向上：一趟一趟扫，width 每次翻倍，趟数 = ceil(log2(n)) */
void merge_sort_bottom_up(Elem a[], int n) {
    Elem tmp[64];
    total_passes = 0;
    for (int width = 1; width < n; width *= 2) {
        total_passes++;
        printf("第 %d 趟: 归并 width=%d, 处理 %d 个元素\n", total_passes, width, n);
        for (int lo = 0; lo < n - width; lo += 2 * width) {
            int mid = lo + width - 1;
            int hi = lo + 2 * width - 1;
            if (hi > n - 1) hi = n - 1;
            merge(a, tmp, lo, mid, hi);
        }
    }
}

int is_stable(const Elem a[], int n) {
    for (int i = 0; i + 1 < n; i++) {
        if (a[i].key == a[i + 1].key && a[i].idx > a[i + 1].idx) return 0;
    }
    return 1;
}

int main(void) {
    Elem a[] = {{5,0},{2,1},{4,2},{6,3},{1,4},{3,5},{2,6},{5,7},{4,8},{1,9}};
    int n = (int)(sizeof(a) / sizeof(a[0]));

    printf("原始序列 (key,idx):");
    for (int i = 0; i < n; i++) printf(" (%d,%d)", a[i].key, a[i].idx);
    printf("\n\n");

    merge_sort_bottom_up(a, n);

    printf("\n排序结果 (key,idx):");
    for (int i = 0; i < n; i++) printf(" (%d,%d)", a[i].key, a[i].idx);
    printf("\n");
    printf("比较次数 = %ld\n", cmp_count);
    printf("归并趟数 = %d, 理论 ceil(log2(n)) = ceil(log2(%d)) = 4\n", total_passes, n);
    printf("是否稳定 = %s (合并时相等取左边)\n", is_stable(a, n) ? "是" : "否");
    printf("空间复杂度 O(n)，时间三档一致 O(n log n)\n");
    return 0;
}
